use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node's HTTPClient handle is scoped to. The host enforces this at
/// the crossing (an out-of-scope request traps). We check it here too, so that
/// one bad subscription becomes a recorded failure instead of trapping the
/// whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key in the shared store where each call's input is recorded.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

/// Extract the lowercase host of an http(s) URL, or None if the URL is not
/// absolute http/https or has no host.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };

    // The authority ends at the first '/', '?' or '#'.
    let authority_end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];

    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Drop any port. These hosts are never IPv6 literals.
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };

    let host = host.trim_end_matches('.').to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

/// Minimal JSON string escaping, so the recorded input is unambiguous.
fn json_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                const HEX: &[u8; 16] = b"0123456789abcdef";
                let v = c as u32;
                out.push_str("\\u00");
                out.push(HEX[((v >> 4) & 0xf) as usize] as char);
                out.push(HEX[(v & 0xf) as usize] as char);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Serialise the subscription list as `{"urls":[...]}`.
fn encode_input(subs: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subs.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        json_string(url, &mut out);
    }
    out.push_str("]}");
    out
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received. This does not affect the output.
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions));

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls.iter() {
            if !is_allowed(url) {
                failures.push(FetchFailure {
                    url: url.clone(),
                    error: String::from("host not in this node's HTTP allowlist"),
                });
                continue;
            }

            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.clone(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.clone(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
